public void init()
{
    next init();

    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
    {
        Fund.visible(true);
    }   
}

protected void lookupRebateAccount(FormControl _formControl, TAMRebatePosting _rebatePosting)
{
    next lookupRebateAccount(_formControl, _rebatePosting);

    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()) &&
        _rebatePosting.RebatePostingType == TAMRebatePostingAccountType::CustVend &&
        _rebatePosting.RebatePaymentType == TAMRebatePaymentType::Fund)
    {
        CustTable::lookupCustomer(_formControl, _rebatePosting.RebateCompany);
    }
}

public void enableFields()
{
    next enableFields();

    if (!FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
    {
        return;
    }

    FormComboBoxControl dynamicAccount = this.design().controlName(formControlStr(TAMRebatePosting, Rebate_DynamicAccount));
    dynamicAccount.clear();
    dynamicAccount.add(enum2Str(TAMRebateDynamicAccount::None));

    if (TAMRebatePosting.ModuleInventCustVend != ModuleInventCustVend::Cust)
    {
        dynamicAccount.add(enum2Str(TAMRebateDynamicAccount::DealAccount));
    }

}
